import java.io.*;
import java.util.*;

public class Solution {
    private static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private static StringTokenizer st;

    private static String readWordString() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) throw new EOFException();
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private static long countLength(long left, long right) {
        return left > right ? 0 : right - left + 1;
    }

    private static long getRight(long left, long count) {
        return left + count - 1;
    }

    public static void main(String[] args) throws IOException {
        readWordString();
        String str = readWordString();
        char[] s = str.toCharArray();
        int n = s.length;
        int upb = n - 1;

        long res = n;

        for (int i = 1; i <= upb; i++) {
            long prefixLen = countLength(0, i - 1);
            long suffixLen = countLength(i, upb);
            if (prefixLen > suffixLen) break;

            boolean equal = true;
            for (int a = 0; a < prefixLen; a++) {
                if (s[a] != s[i + a]) {
                    equal = false;
                    break;
                }
            }
            if (equal) {
                long candidate = 1 + i + (n - i - prefixLen);
                if (candidate < res) res = candidate;
            }
        }

        System.out.println(res);
    }
}

