import java.io.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Solution {
    static class Helper {
        static boolean MULTI_TCs = false;
        static BufferedReader in;
        static BufferedWriter out;
        static StringBuilder sb = new StringBuilder(30);
        static String separatorAutoString = " ";

        static void initIO() throws IOException {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new BufferedWriter(new OutputStreamWriter(System.out));
        }

        static void writeLine() throws IOException {
            out.newLine();
        }

        static void writeSeparator() throws IOException {
            if (separatorAutoString != null && !separatorAutoString.isEmpty()) {
                out.write(separatorAutoString);
            }
        }

        static void writeText(char c) throws IOException {
            out.write(c);
            writeSeparator();
        }

        static void writeText(String s) throws IOException {
            out.write(s);
            writeSeparator();
        }

        static void writeNumber(long i64) throws IOException {
            out.write(Long.toString(i64));
            writeSeparator();
        }

        static void writeNumber(int i32) throws IOException {
            out.write(Integer.toString(i32));
            writeSeparator();
        }

        static void writeNumber(double dec) throws IOException {
            out.write(Double.toString(dec));
            writeSeparator();
        }

        static String readWordString() throws IOException {
            sb.setLength(0);
            int c;
            while ((c = in.read()) != -1) {
                char ch = (char) c;
                if (!isWhitespace(ch)) {
                    sb.append(ch);
                    break;
                }
            }
            if (sb.length() == 0) throw new EOFException();
            while ((c = in.read()) != -1) {
                char ch = (char) c;
                if (isWhitespace(ch)) break;
                sb.append(ch);
            }
            return sb.toString();
        }

        static long readLong64() throws IOException {
            return Long.parseLong(readWordString());
        }

        static char readSingleChar() throws IOException {
            int c;
            while ((c = in.read()) != -1) {
                char ch = (char) c;
                if (!isWhitespace(ch)) return ch;
            }
            throw new EOFException();
        }

        static boolean isWhitespace(char c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }

        static long countLength(long left, long right) {
            return left > right ? 0 : (right - left + 1);
        }

        static long getRight(long left, long count) {
            return left + count - 1;
        }

        static long getLeft(long count, long right) {
            return right - count + 1;
        }

        static List<Long> seq(long low, long high, int skip) {
            List<Long> list = new ArrayList<>();
            for (long i = low; i <= high; i += skip) list.add(i);
            return list;
        }

        static List<Long> seq(long low, long high) {
            return seq(low, high, 1);
        }
    }

