import java.io.*;
import java.util.*;

public class Solution {

    static class Helper {
        static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        static BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        static StringTokenizer st;
        static String separatorAutoString = "";

        static String readWordString() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException();
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        static void writeNumber(long i64) throws IOException {
            bw.write(Long.toString(i64));
            if (!separatorAutoString.isEmpty()) bw.write(separatorAutoString);
        }

        static void writeNumber(int i32) throws IOException {
            bw.write(Integer.toString(i32));
            if (!separatorAutoString.isEmpty()) bw.write(separatorAutoString);
        }

        static void writeLine() throws IOException {
            bw.newLine();
        }

        static void flush() throws IOException {
            bw.flush();
        }

        static long countLength(long left, long right) {
            return left > right ? 0 : right - left + 1;
        }

        static long getRight(long left, long count) {
            return left + count - 1;
        }

        static class ValueRefPointer<T> {
            T value;
            ValueRefPointer(T v) { this.value = v; }
            ValueRefPointer() { this(null); }
            T getValue() { return value; }
            void setValue(T v) { this.value = v; }
            void updateComputeMin(long other) {
                if (value == null) value = (T) Long.valueOf(other);
                else value = (T) Long.valueOf(Math.min((Long) value, other));
            }
        }
    }

    public void __main(int _TCID) throws IOException {
        Helper.readWordString(); // First token ignored as per original logic
