            if (endIdx >= n) continue;

            boolean equal = true;
            for (int k = 0; k < lenLeft; k++) {
                if (s[k] != s[i + k]) {
                    equal = false;
                    break;
                }
            }

            if (equal) {
                long candidate = 1 + n - i;
                res.updateComputeMin(candidate);
            }
        }

        Helper.writeNumber(res.getValue() != null ? res.getValue() : 1L);
        Helper.writeLine();
    }

    public static void main(String[] args) throws IOException {
        int cnt = 1; // MULTI_TCs = false
        Solution sol = new Solution();
        for (int i = 1; i <= cnt; i++) {
            sol.__main(i);
        }
        Helper.flush();
    }
}

